(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  let wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(y*0.012-t*0.15)*8, w2y = Math.cos(x*0.014+t*0.18)*8;
  wx += w2x; wy += w2y;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 1.2],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 2.4],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 3.6],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 4.8],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 6.0],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 1.8],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*40, 0.13, 1.6, 5.2]
  ];
  let aS=0, iS=0, aS2=0;
  for (const [sX,sY,f,sp,ph] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w1 = Math.sin(d*f - t*sp + ph);
    const w2 = Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    aS += w1; iS += w2;
    aS2 += Math.sin(d*f*1.3 - t*sp*0.8 + ph*0.5) * Math.cos(d*f*0.4 + t*sp*1.2);
  }
  const act=aS/8, inh=iS/8, act2=aS2/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const ripple = Math.sin(dist*0.08-t*3)*Math.exp(-dist*0.005)*0.3;
  const cross = Math.sin(sx*0.08+t*0.5)*Math.sin(sy*0.08-t*0.7)*0.25;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + act2*0.4)*2.2);
  const diffusion = Math.tanh((reaction + ripple + cross)*1.8);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+t*1.2)*Math.sin(sy*0.35-t*0.9)*0.15;
  const blend = diffusion*0.55 + cell*0.25 + micro*0.2;
  const v = blend*0.5+0.5;
  const hueShift = Math.sin(t*0.2)*0.15 + Math.sin(ang*0.5+t*0.1)*0.1;
  const pal = [
    [5,12,52],[12,45,95],[18,85,125],[25,130,145],
    [55,165,135],[145,190,80],[210,185,55],[220,140,60],
    [195,90,65],[155,50,70],[100,28,65],[50,18,55],[5,12,52]
  ];
  let idx = (v+hueShift)*(pal.length-1);
  idx = ((idx%1)+1)%1 * (pal.length-1);
  const i = Math.min(idx|0, pal.length-2), f = idx-i;
  const reactionAbs = Math.abs(diffusion);
  const lum = 0.75 + Math.sin(reactionAbs*Math.PI)*0.25;
  const edge = reactionAbs>0.65 ? 1.0 + (reactionAbs-0.65)*0.6 : 0.92 + reactionAbs*0.12;
  const glow = Math.exp(-reactionAbs*2)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*60)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*40)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*80)|0)
  ];
}
